using System;

// PROGRAM: Simulasi Integritas Relasional Relasi Induk-Anak di Memori
public record CustomerEntity(string Id, string Name);
public record AccountEntity(string AccountNumber, string CustomerId, decimal Balance);

public class RelationalDatabaseSimulator
{
    private readonly System.Collections.Generic.Dictionary<string, CustomerEntity> _customers = new();
    private readonly System.Collections.Generic.Dictionary<string, AccountEntity> _accounts = new();

    public void AddCustomer(CustomerEntity customer)
    {
        _customers[customer.Id] = customer;
    }

    public void AddAccount(AccountEntity account)
    {
        // Enforce Foreign Key Constraint: CustomerId WAJIB ada di tabel _customers!
        if (!_customers.ContainsKey(account.CustomerId))
        {
            throw new InvalidOperationException($"FK Violation: CustomerId '{account.CustomerId}' tidak ditemukan!");
        }

        _accounts[account.AccountNumber] = account;
        Console.WriteLine($"[DB INSERT SUCCESS] Akun {account.AccountNumber} terdaftar untuk nasabah {_customers[account.CustomerId].Name}.");
    }
}

public class Program
{
    public static void Main()
    {
        var db = new RelationalDatabaseSimulator();
        db.AddCustomer(new CustomerEntity("CUST-1", "Budi Santoso"));

        // 1. Akun valid (FK lolos)
        db.AddAccount(new AccountEntity("ACC-001", "CUST-1", 1_000_000m));

        // 2. Akun tidak valid (FK violation)
        try
        {
            db.AddAccount(new AccountEntity("ACC-002", "CUST-999_TIDAK_ADA", 500_000m));
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[DB ERROR] {ex.Message}");
        }
    }
}

