using System;
using System.Collections.Generic;

public class NormalizationHelper
{
    public static string[] NormalizeTo1Nf(string id, string name, string? phonesCsv)
    {
        if (string.IsNullOrWhiteSpace(phonesCsv)) return Array.Empty<string>();

        var parts = phonesCsv.Split(',', StringSplitOptions.RemoveEmptyEntries);
        var result = new List<string>();

        foreach (var p in parts)
        {
            string clean = p.Trim();
            if (!string.IsNullOrEmpty(clean))
            {
                result.Add($"{id.Trim()}|{name.Trim()}|{clean}");
            }
        }

        return result.ToArray();
    }

    public static void Main()
    {
        var rows = NormalizeTo1Nf("U-1", "Budi", "0812, 0856");
        foreach (var r in rows) Console.WriteLine(r);
    }
}
